from pathlib import Path
p=Path('artifacts/create_handoff.py')
s=p.read_text(encoding='utf-8')
s=s.replace('simulated role switching, ward/division filtering','email-based demo sign-in with role-scoped access, ward/division filtering')
s=s.replace("('src/App.tsx','Complete dashboard shell, terminal simulator, scope-aware inbox, details drawer, officer action desk, role creation and user onboarding modals.'),", "('src/App.tsx','Shared email sign-in, account-specific dashboard, scope-aware inbox, details drawer, officer action desk, role creation and user onboarding modals.'),('src/services/auth.ts','AuthService interface and demo email/password adapter to replace with the backend function.'),")
s=s.replace('The prototype is a single-page Vite application. The active role and user determine the visible ticket set; localStorage saves demo changes so a judge can switch terminals and revisit the updated queue in the same browser.', 'The prototype is a single-page Vite application served at one shared URL. Sign-in resolves the department email to its assigned user role; that account scope determines which tickets and actions are available. Demo session and workspace changes are stored in this browser.')
s=s.replace('Use the top-right active terminal selector to switch users instantly. The queue, summary cards, SLA overview, and scope label recalculate from the selected user.', 'Use Sign out, then sign in with another department email to preview its dashboard at the same URL. The queue, summary cards, SLA overview, and scope label follow the signed-in account.')
s=s.replace('Frontend-only demo: there is no API, authentication, server-side authorization, audit store, OTP provider, real SLA scheduler, or production database.', 'The email/password flow is demo authentication implemented in the browser. It is not secure, does not provide server-side authorization, and must not be used for real accounts. Replace src/services/auth.ts with the team authentication API and enforce identity, permissions, and scope on the server. There is no audit store, OTP provider, real SLA scheduler, or production database.')
s=s.replace('Data shape or categories: edit src/types/grievance.ts, then update src/data/mockData.ts.', 'Data shape or categories: edit src/types/grievance.ts, then update src/data/mockData.ts.')
s=s.replace('Workspace interactions and UI: edit src/App.tsx.', 'Workspace interactions and UI: edit src/App.tsx. Replace the demo auth adapter in src/services/auth.ts with the team login function.')
p.write_text(s,encoding='utf-8')
